%   T.driftSpan drift [taps per fragment] where the drift Pd checks were verified; T.driftPdLo: their lower bound
LENS = [32 64 128 256];
q = find(LENS == N, 1);
if isempty(q)
    error('synthetic_expect:length', 'RIF length %g is not supported (32, 64, 128 or 256 symbols).', N);
end
